// At launch
BGTaskScheduler.shared.register(forTaskWithIdentifier: "com.app.refresh", using: nil) { task in
    let work = Task { await FeedSync.shared.sync() }
    task.expirationHandler = { work.cancel() }
    Task {
        _ = await work.result
        task.setTaskCompleted(success: !work.isCancelled)
        scheduleRefresh()                  // schedule the next one
    }
}

func scheduleRefresh() {
    let request = BGAppRefreshTaskRequest(identifier: "com.app.refresh")
    request.earliestBeginDate = .now.addingTimeInterval(30 * 60)
    try? BGTaskScheduler.shared.submit(request)
}
